/**
 * @summary Update Item
 */
export const usersUpdateItem = async (
  itemId: string,
  optionalUpdateUser: OptionalUpdateUser,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<DisplayUserOutput> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {}
    if (h instanceof Headers) return Object.fromEntries(h.entries())
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      )
    }
    const headers: Record<string, string | readonly string[]> = {}
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value
    }
    return headers
  }
  const res = await (fetchFn ?? fetch)(getUsersUpdateItemUrl(itemId), {
    ...options,
    method: "PATCH",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(optionalUpdateUser),
  })

  const contentType = (res.headers.get("content-type") ?? "").toLowerCase()
  const body = [204, 205, 304].includes(res.status) ? null : await res.text()
  if (!res.ok) throw createApiFailureError(res, body)
  const parsedBody = body ? (contentType.includes("json") ? JSON.parse(body) : body) : {}
  const data = contentType.includes("json") ? DisplayUser.parse(parsedBody) : parsedBody
  return data
}

